import {apiFetch} from '../core/api.js';
import {el,field,button} from './dom.js';
const MIME='application/vnd.inkmorrow.reference-bundle';
export function bundleControls({dialogs,entries,refresh,live}){
 const root=el('div','','workspace-actions');
 async function post(route,body,headers={}){const response=await apiFetch(`/api/fiction/reference-bundles/${route}`,{method:'POST',headers,body});if(!response.ok){const value=await response.json();throw Error(value.error||'Reference bundle failed.');}return response;}
 root.append(button('Export references…',()=>{
  const selected=entries.map(entry=>({entry,field:field(`${entry.name} (${entry.kind})`,'input',entry.id,{type:'checkbox'})}));const error=el('p');error.setAttribute('role','alert');
  dialogs.openDialog({title:'Keep a private reference bundle',body:[el('p','Select references from this catalogue page. Bundles include private lore and motives and normalized images. They exclude credentials, purchase journals and reference-conditioning permission.'),...selected.map(item=>item.field.wrapper),error],actions:[{label:'Cancel',className:'btn-secondary',onClick:close=>close(true)},{label:'Download selected references',className:'btn-primary',onClick:async close=>{try{const ids=selected.filter(item=>item.field.control.checked).map(item=>item.entry.id);if(!ids.length)throw Error('Select at least one reference.');const response=await post('export',JSON.stringify({ids}),{'Content-Type':'application/json'});const blob=await response.blob();if(!live())return;const href=URL.createObjectURL(blob);const link=el('a');link.href=href;link.download='InkMorrow-references.inkrefs';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(href),1000);close(true);}catch(issue){error.textContent=issue.message;}}}]});
 }),button('Import references…',()=>{
  const file=field('Private reference bundle (up to 64 MB)','input','',{type:'file',accept:'.inkrefs'});const error=el('p');error.setAttribute('role','alert');
  dialogs.openDialog({title:'Import reference copies',body:[el('p','Check the contents first. Import creates new entries even when names match; existing references are preserved. No AI purchase.'),file.wrapper,error],actions:[{label:'Cancel',className:'btn-secondary',onClick:close=>close(true)},{label:'Preview references',className:'btn-primary',onClick:async()=>{try{const selected=file.control.files?.[0];if(!selected||selected.size>64*1024*1024)throw Error('Choose a reference bundle no larger than 64 MB.');const {preview}=await(await post('preview',selected,{'Content-Type':MIME})).json();if(!live())return;const action=crypto.randomUUID();const failure=el('p');failure.setAttribute('role','alert');dialogs.openDialog({title:'Import these private references?',body:[el('p',preview.warning),...preview.entries.map(item=>el('p',`${item.kind}: ${item.name}${item.has_image?' · image':''}${item.same_name?' · same name exists; creates another copy':''}`)),failure],actions:[{label:'Cancel',className:'btn-secondary',onClick:close=>close(true)},{label:'Create new copies',className:'btn-primary',onClick:async close=>{try{await post('import',selected,{'Content-Type':MIME,'Idempotency-Key':action});if(live()){close(true);refresh();}}catch(issue){failure.textContent=issue.message+' Retrying here recovers the same import.';}}}]});}catch(issue){if(live())error.textContent=issue.message;}}}]});
 }));return root;
}
